@spec patternEditor_writethrough_spec  src=tests/specs/patternEditor_writethrough_spec.lua  loc=300  cases=11
@harness   mk, reaper.GetMediaItemTake_Track

# Intent
  design/fx-patterns.md P3.5: write-through commit; curve normalises pb thousandths back to bipolar.
  Drives the real edit -> flush -> rebuild -> write-through path against a fake imgui.

# Helpers
  @fn keyId(name)  @ 13-22
  @fn setKeys(keys, mods)  @ 37-40
  @fn loadPE(deps)  @ 46-52
  @fn notesBody()  @ 60-71
  @fn openNotesBody()  @ 74-82
      -- An OPEN first note followed by a finite one: readback must clip the open tail to the successor.
  @fn polyNotesBody()  @ 86-94
      -- Two overlapping notes on distinct lanes: a poly open keeps them apart; a mono open crushes them
      -- onto lane 1, where the readback clip serialises them as a monophonic run.
  @fn curveBody()  @ 96-105
  @fn ccCurveBody()  @ 108-117
      -- cc-domain curve: points ride a fixed scratch cc verbatim (0..127), no normalisation.
  @fn withEditor(harness, body, poly)  @ 121-127
      -- Open the editor on `body`, capturing each write-through commit; get() reads the latest.
      -- `poly` rides into pe:open: true authors overlapping lanes, absent/false pins everything to lane 1.
  @fn pressDelete(pe)  @ 130-133
      -- Delete the event under the (default row-0) cursor via the real dispatch path.
  @fn approx(a, b)  @ 135

# Cases
  @case 'a checkout edit writes through the commit callback, stripped to the whitelist'  [harness]  @ 139-154
  @case 'readback clips an OPEN note to its successor onset, not the loop length'  [harness]  @ 158-169
  @case 'a curve edit persists as normalised bipolar points, not raw thousandths'  [harness]  @ 173-188
  @case 'a cc-domain curve persists its points verbatim, echoing the domain'  [harness]  @ 192-208
  @case 'Enter commits: the edit stays in the store'  [harness]  @ 212-219
  @case 'Esc cancels: the store is restored to the open snapshot'  [harness]  @ 223-232
  @case 'close does not clobber the committed body via the unbind rebuild'  [harness]  @ 236-243
  @case 'a poly open keeps each authored lane through readback'  [harness]  @ 247-260
  @case 'the same body opened mono flattens every note onto lane 1'  [harness]  @ 264-273
  @case 'the body rpb seeds the editor and rides readback'  [harness]  @ 279-288
  @case 'a body with no rpb commits the default 4'  [harness]  @ 292-298

